    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Sort intervals by start point
    a = sorted(a)
    b = sorted(b)

    # Merge overlapping intervals in b
    merged_b = []
    for start, end in b:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    result = []

    for a_start, a_end in a:
        current_start = a_start
        current_end = a_end

        # Process each b interval that might overlap with current a interval
        for b_start, b_end in merged_b:
            if b_end <= current_start:
                # b interval is completely before current interval
                continue
            if b_start >= current_end:
                # b interval is completely after current interval
                break

            # There is overlap
            if current_start < b_start:
                # Add the part before b interval
                result.append([current_start, b_start])

            # Move current_start past the b interval
            current_start = max(current_start, b_end)

        # Add any remaining part after all b intervals
        if current_start < current_end:
            result.append([current_start, current_end])

    # Merge adjacent intervals that touch
    if not result:
        return []

    merged_result = [result[0]]
    for start, end in result[1:]:
        if start == merged_result[-1][1]:
            # Intervals touch, merge them
            merged_result[-1][1] = end
        else:
            merged_result.append([start, end])

    return merged_result

